mapper.select:
select id, username, usertype, windowsaccount,
displayname , nickname , namezhspell, namezhshortspell, givenname , middlename , familyname ,
gender,
authntype, mobile, email, workemail, workphonenumber,
employeenumber, division, costcenter, organization, departmentid, department, jobtitle, joblevel,
createdby, createddate, modifiedby, modifieddate,
status from mxk_userinfo where instid = #{instId}
and username = #{username}
and employeenumber = #{employeeNumber}
and usertype = #{userType}
and displayname like concat('%',#{displayName},'%')
and departmentid = #{departmentId}
order by sortindex,id

mapper.update:
update mxk_userinfo set
islocked = #{isLocked},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
islocked = #{isLocked}, badpasswordcount = 0,
unlocktime = current_timestamp, modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
password = #{password}, decipherable = #{decipherable}, passwordsettype =#{passwordSetType},
passwordlastsettime = current_timestamp where id = #{id}

update mxk_userinfo set
sharedsecret = #{sharedSecret}, sharedcounter = #{sharedCounter},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
apploginpassword = #{appLoginPassword},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
protectedapps = #{protectedApps},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
passwordquestion = #{passwordQuestion}, passwordanswer = #{passwordAnswer},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo set
authntype = #{authnType},
modifieddate = current_timestamp where id = #{id}

update mxk_userinfo
set status = #{status},
    modifiedby = #{modifiedBy},
    modifieddate = current_timestamp
where id = #{id}
  and instid = #{instId}

mapper.select:
select u.* from mxk_userinfo u where lower(u.username) = lower(#{username}) and u.status = 1
and u.instid = #{instId}
limit 1

select o.*, 1 isPrimary
from mxk_organizations o,
     mxk_userinfo u
where o.instid = u.instid
  and o.id = u.departmentid
  and u.id = #{value}

union all

select o.*, 0 isPrimary
from mxk_organizations o,
     mxk_userinfo_adjunct ua
where o.instid = ua.instid
  and o.id = ua.departmentid
  and ua.userid = #{value}
